/**
 * Payment Controller
 * Generated by BackendForge
 */
const paymentService = require('../services/payment.service');

const paymentController = {
  async createPaymentIntent(req, res, next) {
    try {
      const result = await paymentService.createPaymentIntent(req.userId, req.body);
      res.json({ success: true, message: 'Payment intent created', data: result });
    } catch (error) { next(error); }
  },

  async getPaymentStatus(req, res, next) {
    try {
      const payment = await paymentService.getPaymentStatus(req.params.orderId, req.userId);
      res.json({ success: true, data: { payment } });
    } catch (error) { next(error); }
  },
};

module.exports = paymentController;
